const entry = $json.body.entry[0].changes[0].value;

if (!entry.messages) {
  return []; // status update hai, actual message nahi
}

const msg = entry.messages[0];
const senderNumber = msg.from;
const messageType = msg.type; // "text", "image", "video", "interactive" etc.

let mediaId = null;
let caption = null;
let buttonId = null;
let textBody = null;

if (messageType === 'image') {
  mediaId = msg.image.id;
  caption = msg.image.caption || '';
} else if (messageType === 'video') {
  mediaId = msg.video.id;
  caption = msg.video.caption || '';
} else if (messageType === 'text') {
  textBody = msg.text.body;
} else if (messageType === 'interactive') {
  if (msg.interactive.type === 'button_reply') {
    buttonId = msg.interactive.button_reply.id;
  } else if (msg.interactive.type === 'list_reply') {
    buttonId = msg.interactive.list_reply.id;
  }
}

return [{
  json: {
    sender: senderNumber,
    messageType,
    mediaId,
    caption,
    buttonId,
    textBody
  }
}];

const msg = $('Code in JavaScript').first().json;
const sessionRow = $json;

const sender = msg.sender;
const state = sessionRow.current_state || 'START';
const text = (msg.textBody || '').trim();
const btn = msg.buttonId || '';
const input = text || btn;

let nextState = state;
let reply = '';
let postType = sessionRow.post_type || null;
let mediaId = sessionRow.media_id || null;
let platform = sessionRow.platform || null;
let wantsCaption = sessionRow.wants_caption ?? null;
let captionMode = sessionRow.caption_mode || null;
let captionText = sessionRow.caption_text || null;
let aiPrompt = sessionRow.ai_prompt || null;
let captionEdited = sessionRow.caption_edited ?? false;
let triggerPost = false;

function confirmText() {
  const p = platform === 'both' ? 'Facebook and Instagram' : platform === 'facebook' ? 'Facebook' : 'Instagram';
  return `Please confirm:\n📌 Type: ${postType}\n📝 Caption: ${captionText || '(no caption)'}\n📍 Platform: ${p}\n\nDo you want to post this?\n1. Yes\n2. No`;
}

if (state === 'START') {
  reply = "Hello! What would you like to post?\n1. Image\n2. Video";
  nextState = 'AWAIT_TYPE';
} else if (state === 'AWAIT_TYPE') {
  if (input === '1') { postType = 'image'; reply = "Great, please send the image now."; nextState = 'AWAIT_MEDIA'; }
  else if (input === '2') { postType = 'video'; reply = "Great, please send the video now."; nextState = 'AWAIT_MEDIA'; }
  else reply = "Please reply with 1 (Image) or 2 (Video).";
} else if (state === 'AWAIT_MEDIA') {
  if (msg.messageType === postType && msg.mediaId) {
    mediaId = msg.mediaId;
    reply = "Got it! Where would you like to post this?\n1. Facebook\n2. Instagram\n3. Both";
    nextState = 'AWAIT_PLATFORM';
  } else reply = `Please send ${postType === 'image' ? 'an image' : 'a video'}.`;
} else if (state === 'AWAIT_PLATFORM') {
  if (['1','2','3'].includes(input)) {
    platform = input === '1' ? 'facebook' : input === '2' ? 'instagram' : 'both';
    reply = "Would you like a caption?\n1. Yes\n2. No";
    nextState = 'AWAIT_CAPTION_YN';
  } else reply = "Please reply with 1, 2, or 3.";
} else if (state === 'AWAIT_CAPTION_YN') {
  if (input === '2') { wantsCaption = false; captionText = ''; reply = confirmText(); nextState = 'AWAIT_CONFIRM'; }
  else if (input === '1') { wantsCaption = true; reply = "Would you like to write it yourself or let AI write it?\n1. I'll write it\n2. AI"; nextState = 'AWAIT_CAPTION_MODE'; }
  else reply = "Please reply with 1 (Yes) or 2 (No).";
} else if (state === 'AWAIT_CAPTION_MODE') {
  if (input === '1') { captionMode = 'self'; reply = "Please type and send your caption."; nextState = 'AWAIT_CAPTION_TEXT'; }
  else if (input === '2') { captionMode = 'ai'; reply = "Would you like to give a style/prompt yourself, or should I look at the photo/video and decide?\n1. I'll give a prompt\n2. You decide (based on the photo/video)"; nextState = 'AWAIT_AI_SOURCE'; }
  else reply = "Please reply with 1 or 2.";
} else if (state === 'AWAIT_AI_SOURCE') {
  if (input === '1') { reply = "Please type your prompt (e.g. 'funny tone', 'professional')."; nextState = 'AWAIT_AI_PROMPT'; }
  else if (input === '2') { aiPrompt = ''; reply = "Okay, generating a caption based on the media... ⏳"; nextState = 'AI_GENERATING'; }
  else reply = "Please reply with 1 or 2.";
} else if (state === 'AWAIT_AI_PROMPT') {
  aiPrompt = msg.textBody || '';
  reply = "Okay, generating your caption... ⏳";
  nextState = 'AI_GENERATING';
} else if (state === 'AI_GENERATING') {
  reply = "Please wait, the caption is still being generated... ⏳";
  nextState = 'AI_GENERATING';
} else if (state === 'AWAIT_AI_CONFIRM') {
  if (input === '1') { reply = confirmText(); nextState = 'AWAIT_CONFIRM'; }
  else if (input === '2') { reply = "What would you like to change? Please describe it (e.g. 'make it funnier', 'make it shorter')."; nextState = 'AWAIT_AI_FEEDBACK'; }
  else if (input === '3') { reply = "Okay, please type and send your caption."; nextState = 'AWAIT_CAPTION_TEXT'; }
  else reply = "Please reply with 1 (Keep it), 2 (Request changes), or 3 (I'll write it myself).";
} else if (state === 'AWAIT_AI_FEEDBACK') {
  const feedback = msg.textBody || '';
  aiPrompt = `Previous caption was: "${captionText}". User requested this change: "${feedback}". Rewrite the caption incorporating this feedback.`;
  captionEdited = true;
  reply = "Okay, updating the caption... ⏳";
  nextState = 'AI_GENERATING';
} else if (state === 'AWAIT_CAPTION_TEXT') {
  captionText = msg.textBody || '';
  reply = confirmText();
  nextState = 'AWAIT_CONFIRM';
} else if (state === 'AWAIT_CONFIRM') {
  if (input === '1') { reply = "Posting now... ✅"; nextState = 'DONE'; triggerPost = true; }
  else if (input === '2') { reply = "Cancelled. Send anything to start a new post."; nextState = 'START'; postType=null; mediaId=null; platform=null; wantsCaption=null; captionMode=null; captionText=null; aiPrompt=null; captionEdited=false; }
  else reply = "Please reply with 1 (Yes) or 2 (No).";
} else if (state === 'DONE') {
  reply = "Send anything to start a new post.";
  nextState = 'START'; postType=null; mediaId=null; platform=null; wantsCaption=null; captionMode=null; captionText=null; aiPrompt=null; captionEdited=false;
}

return [{ json: { sender, nextState, reply, postType, mediaId, platform, wantsCaption, captionMode, captionText, aiPrompt, triggerPost, captionEdited } }];

const s = $('State Machine').first().json;
if (!s.triggerPost) return [];

return [{
  json: {
    sender: s.sender,
    messageType: s.postType,
    mediaId: s.mediaId,
    caption: s.captionText,
    platform: s.platform
  }
}];

const item = $input.item;
const binaryPropertyName = 'data';

const buffer = await this.helpers.getBinaryDataBuffer(0, binaryPropertyName);
const base64 = buffer.toString('base64');
const mimeType = item.binary[binaryPropertyName].mimeType;

return [{
  json: {
    base64: base64,
    mimeType: mimeType
  }
}];

const s = $('State Machine').first().json;
const gemini = $json;
const captionText = gemini.candidates[0].content.parts[0].text.trim();

return [{
  json: {
    sender: s.sender,
    nextState: 'AWAIT_AI_CONFIRM',
    reply: `Here's the caption I came up with:\n\n"${captionText}"\n\nKeep it?\n1. Yes, keep it\n2. Request changes\n3. I'll write it myself`,
    postType: s.postType,
    mediaId: s.mediaId,
    platform: s.platform,
    wantsCaption: s.wantsCaption,
    captionMode: s.captionMode,
    captionText: captionText,
    aiPrompt: s.aiPrompt,
    triggerPost: false
  }
}];

const s = $('State Machine').first().json;
const media = $json;

const promptText = (s.aiPrompt
  ? `Write an engaging, natural English social media caption for this ${s.postType}. Style/instructions: ${s.aiPrompt}`
  : `Write an engaging, natural English social media caption for this ${s.postType}.`
) + ' Keep it concise (1-2 sentences), suitable for Instagram/Facebook, and include 1-3 relevant emojis. Return ONLY the caption text, nothing else.';

return [{
  json: {
    promptText,
    base64: media.base64,
    mimeType: media.mimeType
  }
}];

const s = $('State Machine').first().json;
let postLink = '';
let status = 'Success';

try {
  const fbResult = $('Post Image FB').first()?.json || $('Post Video FB').first()?.json;
  if (fbResult?.id) postLink = `https://facebook.com/${fbResult.id}`;
} catch (e) {}

try {
  const igResult = $('Publish IG Post').first()?.json || $('Publish IG Video').first()?.json;
  if (igResult?.id) postLink += (postLink ? ' | ' : '') + `https://instagram.com/p/${igResult.id}`;
} catch (e) {}

const platformLabel = s.platform === 'both' ? 'Facebook/Instagram'
  : s.platform === 'facebook' ? 'Only Facebook'
  : s.platform === 'instagram' ? 'Only Instagram'
  : s.platform;

return [{
  json: {
    dateTime: new Date().toISOString(),
    postType: s.postType,
    hasCaption: s.wantsCaption ? 'Yes' : 'No',
    captionBy: s.captionMode === 'ai' ? 'AI' : (s.captionMode === 'self' ? 'Self' : 'N/A'),
    edited: s.captionEdited ? 'Yes' : 'No',
    platform: platformLabel,
    postLink: postLink || 'N/A',
    executionId: $execution.id,
    status: status,
    error: ''
  }
}];
